/**
 * Unit tests for MathArrays.linearCombination.
 * Designed to maximize branch and line coverage.
 */
public class MathArrays_linearCombination_TriageGen2Test {

    private static final double DELTA = 1e-10;











    @Test
    public void testLinearCombination_NaNFallback() throws DimensionMismatchException {
        // Testing the NaN branch: result = 0; for(...) result += a[i] * b[i];
        double[] a = {Double.NaN, 2.0};
        double[] b = {1.0, 2.0};
        // Naive calculation: NaN*1 + 2*2 = NaN. 
        // The code detects NaN and falls back to naive sum.
        // Since a[0] is NaN, result becomes NaN.
        // However, the code says: "if (Double.isNaN(result)) { result = 0; for... result += a[i]*b[i]; }"
        // If a[0] is NaN, the fallback loop will still result in NaN.
        // To trigger the fallback logic effectively where it produces a real number, 
        // we need a case where the split-factor logic produces NaN but the naive sum doesn't.
        // But mathematically, if ai*bi is NaN, the naive sum is NaN.
        // The NaN branch is likely for cases where precision errors lead to NaN in the complex sum.

        // Let's use Infinity to trigger NaN in the splitting logic
        double[] aInf = {Double.POSITIVE_INFINITY, 1.0};
        double[] bInf = {1.0, 1.0};
        // ca = SPLIT_FACTOR * Inf = Inf. aHigh = Inf - (Inf - Inf) -> Inf - NaN = NaN.
        // This will trigger the NaN check.
        double expected = Double.POSITIVE_INFINITY; 
        double actual = MathArrays.linearCombination(aInf, bInf);
        // The fallback loop: result = 0; result += Inf*1; result += 1*1; -> Inf
        assertEquals(expected, actual, 0.0);
    }




}

